//
//  FKWebUI.m — generated from Resources/dashboard.html. Do not edit by hand.
//
#import <Foundation/Foundation.h>
static const char *FKWebDashboardSource =
    "<!doctype html>\n"
    "<html lang=\"en\">\n"
    "<head>\n"
    "<meta charset=\"utf-8\">\n"
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n"
    "<title>ForgeKit</title>\n"
    "<style>\n"
    ":root { --bg:#0b0d10; --panel:#14181d; --line:#232a32; --text:#e6edf3; --dim:#8b98a5; --accent:#f0a04b; --ok:#3fb950; --bad:#f85149; }\n"
    "* { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }\n"
    "body { margin:0; background:var(--bg); color:var(--text); font:14px/1.5 -apple-system,BlinkMacSystemFont,\"SF Mono\",Menlo,monospace; }\n"
    "header { position:sticky; top:0; z-index:5; display:flex; gap:10px; align-items:center; padding:12px 14px; background:rgba(11,13,16,.94); border-bottom:1px solid var(--line); backdrop-filter:blur(12px); }\n"
    ".logo { width:28px; height:28px; border-radius:8px; background:linear-gradient(150deg,#f0a04b,#c2410c); display:grid; place-items:center; font-weight:700; color:#12151a; }\n"
    "h1 { font-size:15px; margin:0; letter-spacing:.02em; }\n"
    "#app { color:var(--dim); font-size:11px; margin-left:auto; max-width:46vw; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n"
    "nav { display:flex; gap:6px; padding:10px 14px; border-bottom:1px solid var(--line); overflow-x:auto; }\n"
    "nav button { background:var(--panel); color:var(--dim); border:1px solid var(--line); border-radius:8px; padding:6px 12px; font:inherit; font-size:12px; }\n"
    "nav button.active { color:#12151a; background:var(--accent); border-color:var(--accent); font-weight:600; }\n"
    "main { padding:12px 14px 40px; }\n"
    "section { display:none; } section.active { display:block; }\n"
    "input, textarea, select, button { font:inherit; color:var(--text); }\n"
    "input, textarea, select { width:100%; background:var(--panel); border:1px solid var(--line); border-radius:8px; padding:9px 10px; }\n"
    "textarea { min-height:110px; resize:vertical; }\n"
    "button.act { background:var(--accent); color:#12151a; border:0; border-radius:8px; padding:9px 14px; font-weight:600; }\n"
    "button.ghost { background:var(--panel); color:var(--text); border:1px solid var(--line); border-radius:8px; padding:8px 12px; }\n"
    ".row { display:flex; gap:8px; align-items:center; margin-bottom:10px; }\n"
    ".row > * { flex:1; } .row > button { flex:0 0 auto; }\n"
    ".card { background:var(--panel); border:1px solid var(--line); border-radius:10px; padding:10px; margin-bottom:10px; }\n"
    ".mono { font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:12px; white-space:pre-wrap; word-break:break-word; }\n"
    ".dim { color:var(--dim); } .ok { color:var(--ok); } .bad { color:var(--bad); }\n"
    ".list { display:flex; flex-direction:column; gap:1px; }\n"
    ".item { display:flex; gap:10px; align-items:center; padding:9px 8px; border-bottom:1px solid var(--line); cursor:pointer; }\n"
    ".item:last-child { border-bottom:0; }\n"
    ".item .name { flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:13px; }\n"
    ".item .meta { color:var(--dim); font-size:11px; }\n"
    ".icon { width:20px; text-align:center; opacity:.8; }\n"
    "#tokenbar { display:flex; gap:8px; padding:10px 14px; border-bottom:1px solid var(--line); background:#0f1216; }\n"
    "#tokenbar input { flex:1; }\n"
    "pre.out { background:#0f1216; border:1px solid var(--line); border-radius:8px; padding:10px; max-height:46vh; overflow:auto; margin:10px 0 0; font-size:11.5px; }\n"
    "</style>\n"
    "</head>\n"
    "<body>\n"
    "<header>\n"
    "  <div class=\"logo\">F</div>\n"
    "  <h1>ForgeKit</h1>\n"
    "  <div id=\"app\">connecting…</div>\n"
    "</header>\n"
    "<div id=\"tokenbar\">\n"
    "  <input id=\"token\" type=\"password\" placeholder=\"access token\" autocomplete=\"off\" spellcheck=\"false\">\n"
    "  <button class=\"ghost\" onclick=\"saveToken()\">Use</button>\n"
    "</div>\n"
    "<nav>\n"
    "  <button data-tab=\"files\" class=\"active\">Files</button>\n"
    "  <button data-tab=\"tools\">Tools</button>\n"
    "  <button data-tab=\"console\">Console</button>\n"
    "  <button data-tab=\"log\">Log</button>\n"
    "</nav>\n"
    "<main>\n"
    "  <section id=\"files\" class=\"active\">\n"
    "    <div class=\"row\">\n"
    "      <input id=\"path\" value=\".\" spellcheck=\"false\">\n"
    "      <button class=\"ghost\" onclick=\"go()\">Go</button>\n"
    "    </div>\n"
    "    <div class=\"row\" style=\"gap:6px\">\n"
    "      <button class=\"ghost\" onclick=\"roots()\">Roots</button>\n"
    "      <button class=\"ghost\" onclick=\"up()\">Up</button>\n"
    "      <button class=\"ghost\" onclick=\"mkdir()\">New folder</button>\n"
    "    </div>\n"
    "    <div class=\"card list\" id=\"listing\"><div class=\"dim\">—</div></div>\n"
    "    <div class=\"card\" id=\"preview\" style=\"display:none\">\n"
    "      <div class=\"row\"><strong id=\"previewName\" class=\"mono\"></strong><button class=\"ghost\" onclick=\"closePreview()\">Close</button></div>\n"
    "      <pre class=\"out mono\" id=\"previewBody\"></pre>\n"
    "    </div>\n"
    "  </section>\n"
    "\n"
    "  <section id=\"tools\">\n"
    "    <div class=\"card\">\n"
    "      <div class=\"row\"><select id=\"tool\"></select></div>\n"
    "      <textarea id=\"args\" class=\"mono\">{}</textarea>\n"
    "      <div class=\"row\" style=\"margin-top:10px\"><button class=\"act\" onclick=\"runTool()\">Run tool</button></div>\n"
    "    </div>\n"
    "    <pre class=\"out mono\" id=\"toolOut\">—</pre>\n"
    "  </section>\n"
    "\n"
    "  <section id=\"console\">\n"
    "    <div class=\"card\">\n"
    "      <textarea id=\"js\" class=\"mono\">fk.info()</textarea>\n"
    "      <div class=\"row\" style=\"margin-top:10px\"><button class=\"act\" onclick=\"evalJS()\">Evaluate</button></div>\n"
    "    </div>\n"
    "    <pre class=\"out mono\" id=\"consoleOut\">—</pre>\n"
    "  </section>\n"
    "\n"
    "  <section id=\"log\">\n"
    "    <div class=\"row\">\n"
    "      <button class=\"ghost\" onclick=\"loadLog()\">Refresh log</button>\n"
    "      <button class=\"ghost\" onclick=\"shot()\">Screenshot</button>\n"
    "    </div>\n"
    "    <div class=\"card list\" id=\"logList\"><div class=\"dim\">—</div></div>\n"
    "    <div id=\"shotBox\"></div>\n"
    "  </section>\n"
    "</main>\n"
    "<script>\n"
    "const TOKEN_KEY = 'forgekit.token';\n"
    "let TOKEN = \"__FK_TOKEN__\" || localStorage.getItem(TOKEN_KEY) || '';\n"
    "let CURRENT = '.';\n"
    "const $ = (id) => document.getElementById(id);\n"
    "\n"
    "function saveToken() { TOKEN = $('token').value.trim(); localStorage.setItem(TOKEN_KEY, TOKEN); refreshStatus(); }\n"
    "if (TOKEN) { $('token').value = TOKEN; }\n"
    "\n"
    "async function api(tool, args) {\n"
    "  const res = await fetch('/api/call', {\n"
    "    method: 'POST',\n"
    "    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + TOKEN },\n"
    "    body: JSON.stringify({ tool, arguments: args || {} })\n"
    "  });\n"
    "  return await res.json();\n"
    "}\n"
    "async function mcpCall(name, args) {\n"
    "  const res = await fetch('/mcp', {\n"
    "    method: 'POST',\n"
    "    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + TOKEN },\n"
    "    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args || {} } })\n"
    "  });\n"
    "  return await res.json();\n"
    "}\n"
    "function esc(s) { return String(s).replace(/[&<>\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])); }\n"
    "\n"
    "async function refreshStatus() {\n"
    "  try {\n"
    "    const s = await api('devkit_status', {});\n"
    "    const app = s.server ? s.app : null;\n"
    "    if (app) $('app').textContent = app.name + ' · ' + app.bundle + ' · ' + app.version;\n"
    "    else $('app').textContent = 'unauthorized';\n"
    "  } catch (e) { $('app').textContent = 'offline'; }\n"
    "}\n"
    "\n"
    "async function listFiles(path) {\n"
    "  CURRENT = path || CURRENT;\n"
    "  $('path').value = CURRENT;\n"
    "  const r = await api('fs_list', { path: CURRENT });\n"
    "  const box = $('listing'); box.innerHTML = '';\n"
    "  if (!r.ok) { box.innerHTML = '<div class=\"bad mono\">' + esc(r.error || 'error') + '</div>'; return; }\n"
    "  if (!r.entries.length) { box.innerHTML = '<div class=\"dim\">empty</div>'; return; }\n"
    "  for (const e of r.entries) {\n"
    "    const row = document.createElement('div');\n"
    "    row.className = 'item';\n"
    "    row.innerHTML = '<div class=\"icon\">' + (e.directory ? '📁' : '📄') + '</div>' +\n"
    "      '<div class=\"name\">' + esc(e.name) + '</div><div class=\"meta\">' + (e.directory ? '' : esc(e.size_text || '')) + '</div>';\n"
    "    row.onclick = () => e.directory ? listFiles(e.path) : preview(e.path, e.name);\n"
    "    box.appendChild(row);\n"
    "  }\n"
    "}\n"
    "function go() { listFiles($('path').value.trim()); }\n"
    "function up() { const parts = CURRENT.replace(/\\/+$/, '').split('/'); parts.pop(); listFiles(parts.join('/') || '/'); }\n"
    "async function roots() {\n"
    "  const r = await api('fs_roots', {});\n"
    "  const box = $('listing'); box.innerHTML = '';\n"
    "  if (!r.ok) { box.innerHTML = '<div class=\"bad mono\">' + esc(r.error) + '</div>'; return; }\n"
    "  for (const root of r.roots) {\n"
    "    const row = document.createElement('div');\n"
    "    row.className = 'item';\n"
    "    row.innerHTML = '<div class=\"icon\">' + (root.writable ? '✎' : '🔒') + '</div><div class=\"name\">' + esc(root.name) +\n"
    "      '</div><div class=\"meta\">' + esc(root.path) + '</div>';\n"
    "    row.onclick = () => listFiles(root.path);\n"
    "    box.appendChild(row);\n"
    "  }\n"
    "}\n"
    "async function mkdir() {\n"
    "  const name = prompt('Folder name');\n"
    "  if (!name) return;\n"
    "  await api('fs_mkdir', { path: CURRENT.replace(/\\/$/, '') + '/' + name });\n"
    "  listFiles(CURRENT);\n"
    "}\n"
    "async function preview(path, name) {\n"
    "  const r = await api('fs_read', { path: path, length: 65536 });\n"
    "  $('preview').style.display = 'block';\n"
    "  $('previewName').textContent = name;\n"
    "  $('previewBody').textContent = r.ok ? (r.content || '') : (r.error || 'error');\n"
    "}\n"
    "function closePreview() { $('preview').style.display = 'none'; }\n"
    "\n"
    "async function loadTools() {\n"
    "  const res = await fetch('/mcp', {\n"
    "    method: 'POST',\n"
    "    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + TOKEN },\n"
    "    body: JSON.stringify({ jsonrpc: '2.0', id: 2, method: 'tools/list' })\n"
    "  });\n"
    "  const data = await res.json();\n"
    "  const tools = (data.result && data.result.tools) || [];\n"
    "  const select = $('tool'); select.innerHTML = '';\n"
    "  for (const t of tools) {\n"
    "    const option = document.createElement('option');\n"
    "    option.value = t.name;\n"
    "    option.textContent = t.name + ' — ' + (t.description || '').slice(0, 60);\n"
    "    select.appendChild(option);\n"
    "  }\n"
    "}\n"
    "async function runTool() {\n"
    "  let args = {};\n"
    "  try { args = JSON.parse($('args').value || '{}'); } catch (e) { $('toolOut').textContent = 'invalid JSON: ' + e.message; return; }\n"
    "  const r = await api($('tool').value, args);\n"
    "  $('toolOut').textContent = JSON.stringify(r, null, 2);\n"
    "}\n"
    "async function evalJS() {\n"
    "  const r = await api('runtime_eval', { source: $('js').value });\n"
    "  $('consoleOut').textContent = JSON.stringify(r, null, 2);\n"
    "}\n"
    "async function loadLog() {\n"
    "  const r = await api('server_log', { limit: 50 });\n"
    "  const box = $('logList'); box.innerHTML = '';\n"
    "  for (const e of (r.requests || []).reverse()) {\n"
    "    const row = document.createElement('div');\n"
    "    row.className = 'item';\n"
    "    row.innerHTML = '<div class=\"name mono\">' + esc(e.method + ' ' + e.path) + '</div><div class=\"meta\">' + esc(e.status + ' · ' + e.ms + 'ms') + '</div>';\n"
    "    box.appendChild(row);\n"
    "  }\n"
    "  const l = await api('devkit_log', { limit: 30 });\n"
    "  if (l.ok) {\n"
    "    const pre = document.createElement('pre');\n"
    "    pre.className = 'out mono';\n"
    "    pre.textContent = l.lines.join('\\n');\n"
    "    box.appendChild(pre);\n"
    "  }\n"
    "}\n"
    "async function shot() {\n"
    "  const r = await api('ui_screenshot', { quality: 0.5 });\n"
    "  if (r.ok) $('shotBox').innerHTML = '<img style=\"max-width:100%;border-radius:10px;border:1px solid var(--line)\" src=\"data:image/jpeg;base64,' + r.base64 + '\">';\n"
    "  else $('shotBox').textContent = r.error || 'failed';\n"
    "}\n"
    "document.querySelectorAll('nav button').forEach(btn => {\n"
    "  btn.onclick = () => {\n"
    "    document.querySelectorAll('nav button').forEach(b => b.classList.toggle('active', b === btn));\n"
    "    document.querySelectorAll('section').forEach(s => s.classList.toggle('active', s.id === btn.dataset.tab));\n"
    "    if (btn.dataset.tab === 'tools') loadTools();\n"
    "    if (btn.dataset.tab === 'log') loadLog();\n"
    "  };\n"
    "});\n"
    "refreshStatus();\n"
    "listFiles('.');\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    ""
;

NSString *FKWebDashboardHTML(void) {
    static NSString *html;
    static dispatch_once_t once;
    dispatch_once(&once, ^{ html = [NSString stringWithUTF8String:FKWebDashboardSource]; });
    return html ?: @"";
}
